      set('--dsw-alias-file-diff-added-gutter', rgba(p.success, 0.08));
      set('--dsw-alias-file-diff-added-marker', p.success);
      set('--dsw-alias-file-diff-deleted-bg', rgba(p.error, 0.14));
      set('--dsw-alias-file-diff-deleted-gutter', rgba(p.error, 0.08));
      set('--dsw-alias-file-diff-deleted-marker', p.error);
      set('--dsw-alias-bg-mask-drop', rgba(p.bg, 0.72));
      set('--dsw-alias-bg-mask-photo', 'rgba(0,0,0,0.88)');
      set('--dsw-alias-brand-primary-new-colorprimary-new-color', p.accentHover);
