      bPos.push('0 0'); bSize.push('auto'); bRep.push('no-repeat');
      L.push(sel + '::before{content:"";position:fixed;inset:0;z-index:-2;pointer-events:none;');
      L.push('  background-image:' + bImg.join(',') + ';');
      L.push('  background-position:' + bPos.join(',') + ';');
      L.push('  background-size:' + bSize.join(',') + ';');
      L.push('  background-repeat:' + bRep.join(',') + ';');
      L.push('}');
      L.push(sel + '::after{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;');
      L.push('  background-image:' + NOISE_URI + ';mix-blend-mode:soft-light;opacity:' + (0.04 + glow * 0.05).toFixed(3) + ';}');
      /* 结构性整屏面一律放空，否则水印只在缝里露一角：
         AppFrame(.xxx_frame) / 中栏 / 侧栏 / 会话根(.xxx_root[data-phase]) 都在铺整屏不透明底。 */
      L.push(sel + ' [id="root"],' + sel + ' [class$="_frame"],' + sel + ' [class*="_frame "],' + sel + ' [class*="_centerCol"],');
      L.push(sel + ' [class*="_sidebarCol"],' + sel + ' [class*="_rightbarCol"],' + sel + ' [class*="_root"][data-phase],');
      L.push(sel + ' [data-content-phase],' + sel + ' [role="tree"]{background-color:transparent !important;}');
      /* 少数靠不透明底遮住滚动内容的粘性行，补回来（bg-base 现在是透明的）。 */
      L.push(sel + ' [data-disclosure-row],' + sel + ' [class*="_compactionButton"]{background-color:' + p.layer2 + ' !important;}');
      /* 高度链兜底（默认关）：宿主是 html,body,#root{height:100%} + .frame{height:100%;overflow:hidden}
         的固定壳。万一有插件往文档里塞内容把链断掉，页面会长出可滚动的一整截空白，这里能重新钉死。
         因为它是全局行为改动（封掉页面级滚动），默认不启用，只在设置里手动开。 */
      if (prefs.pageGuard) {
        L.push('html:has(body[' + BODY_ATTR + ']){height:100%;overflow:hidden;}');
        L.push('body[' + BODY_ATTR + ']{height:100%;overflow:hidden;}');
        L.push('body[' + BODY_ATTR + '] [id=\"root\"]{height:100%;}');
      }

      /* 文字与控件 */
      L.push(sel + ' *{scrollbar-color:' + rgba(p.label, 0.22) + ' transparent;}');
      L.push(sel + ' ::selection{background:' + rgba(p.accent, 0.38) + ';color:' + p.label + ';}');
      L.push(sel + ' h1,' + sel + ' h2,' + sel + ' h3{text-shadow:0 0 10px ' + rgba(p.glow, (0.30 * glow).toFixed(3)) + ';}');
      L.push(sel + ' button:focus-visible,' + sel + ' a:focus-visible{outline:1px solid ' + p.accentHover + ';outline-offset:1px;}');
      L.push(sel + ' img{video-rendering:auto;}');
      L.push(sel + ' ::-webkit-scrollbar{width:8px;height:8px;}');
      L.push(sel + ' ::-webkit-scrollbar-thumb{background:' + rgba(p.label, 0.22) + ';border-radius:2px;}');
      L.push(sel + ' ::-webkit-scrollbar-thumb:hover{background:' + rgba(p.label, 0.40) + ';}');
      L.push(sel + ' ::-webkit-scrollbar-track{background:transparent;}');

      /* 覆盖层（数据雨 / 扫描线 / 暗角 / HUD） */
      L.push('.lm-fx{position:fixed;inset:0;z-index:2;pointer-events:none;overflow:hidden;font-family:' + FONT_STACK + ';}');
      L.push('.lm-rain{position:absolute;inset:0;opacity:' + (0.16 + 0.14 * glow).toFixed(3) + ';-webkit-mask-image:linear-gradient(180deg,transparent 0,#000 18%,#000 72%,transparent 100%);mask-image:linear-gradient(180deg,transparent 0,#000 18%,#000 72%,transparent 100%);}');
      L.push('.lm-col{position:absolute;top:-20%;width:1ch;white-space:pre-wrap;word-break:break-all;line-height:1.06;');
      L.push('  color:var(--lm-rain);text-shadow:0 0 6px ' + rgba(p.rain, 0.55) + ';');
      L.push('  animation-name:lm-fall;animation-timing-function:linear;animation-iteration-count:infinite;}');
      L.push('.lm-head{color:' + rgba(p.label, 0.95) + ';text-shadow:0 0 8px ' + rgba(p.glow, 0.8) + ';}');
      L.push('@keyframes lm-fall{from{transform:translateY(-100%);}to{transform:translateY(100vh);}}');
      L.push('.lm-scan{position:absolute;inset:0;');
