      L.push('.lm-sweep{position:absolute;left:0;right:0;height:22vh;top:-22vh;background:linear-gradient(180deg,transparent,' + rgba(p.glow, Math.min(0.4, Number(scanAlpha) * 1.6).toFixed(3)) + ',transparent);animation:lm-sweep 7.5s linear infinite;}');
      L.push('@keyframes lm-sweep{from{transform:translateY(0);}to{transform:translateY(130vh);}}');
      L.push('.lm-vig{position:absolute;inset:0;background:radial-gradient(120% 90% at 50% 50%,transparent 42%,rgba(0,0,0,0.55) 100%);}');
      /* 徽记水印 + 背景纹样（随部门预设切换） */
      L.push('.lm-pat{position:absolute;inset:0;overflow:hidden;}');
      L.push('.lm-radar{position:absolute;left:50%;top:50%;width:190vmax;height:190vmax;margin:-95vmax 0 0 -95vmax;background:conic-gradient(from 0deg,' + rgba(p.glow, 0.22) + ' 0deg,' + rgba(p.glow, 0) + ' 30deg,' + rgba(p.glow, 0) + ' 360deg);animation:lm-rot 8s linear infinite;}');
      L.push('@keyframes lm-rot{to{transform:rotate(360deg);}}');
      /* 背景徽记（覆盖层）：和数据雨、扫描线同级，强度由内联 opacity 控制。 */
      L.push('.lm-wm{position:absolute;left:50%;top:50%;z-index:2;width:min(72vh,72vw);height:min(72vh,72vw);transform:translate(-50%,-50%);pointer-events:none;animation:lm-wm-pulse 22s ease-in-out infinite;}');
      L.push('.lm-wm-mark{width:100%;height:100%;display:inline-flex;align-items:center;justify-content:center;object-fit:contain;color:' + st.colors.main + ';}');
      L.push('@keyframes lm-wm-pulse{0%,100%{transform:translate(-50%,-50%) scale(1);}50%{transform:translate(-50%,-50%) scale(1.045);}}');
      /* .lm-fx 内部分层表（子元素全是 position:absolute，所以 z-index 生效）：
         纹样 1 ＜ 徽记 2 ＜ 数据雨 3 ＜ 扫描线/过扫 4 ＜ 暗角 5 ＜ 角标读数 6 / 诊断 7。
         军委的旋转光束与国安的同心圆都在第 1 层，永远被徽记压在下面。 */
      L.push('.lm-pat,.lm-rings,.lm-cross{z-index:1;}');
      L.push('.lm-rain{z-index:3;}');
      L.push('.lm-scan,.lm-sweep{z-index:4;}');
      L.push('.lm-vig{z-index:5;}');
      L.push('.lm-hud{z-index:6;}');
      L.push('.lm-diag{z-index:7;}');
      L.push('.lm-rings{position:absolute;inset:0;background:repeating-radial-gradient(circle at 50% 50%,' + rgba(p.label, 0.11) + ' 0 1px,transparent 1px 82px),repeating-linear-gradient(0deg,' + rgba(p.label, 0.05) + ' 0 1px,transparent 1px 26px),repeating-linear-gradient(90deg,' + rgba(p.label, 0.05) + ' 0 1px,transparent 1px 26px);}');
      L.push('.lm-cross{position:absolute;inset:0;background:linear-gradient(90deg,transparent calc(50% - 0.5px),' + rgba(p.glow, 0.12) + ' calc(50% - 0.5px) calc(50% + 0.5px),transparent calc(50% + 0.5px)),linear-gradient(0deg,transparent calc(50% - 0.5px),' + rgba(p.glow, 0.12) + ' calc(50% - 0.5px) calc(50% + 0.5px),transparent calc(50% + 0.5px));animation:lm-flicker 9s steps(30,end) infinite;}');
      L.push('@keyframes lm-breathe{0%,100%{transform:scale(1);opacity:0.85;}50%{transform:scale(1.045);opacity:1;}}');
