        document.body.setAttribute(BODY_ATTR, presetById(prefs.state).id);
        for (var s = 0; s < SKIN_ATTRS.length; s++) document.body.setAttribute(SKIN_ATTRS[s], SKIN_ID);
        detectConflicts();
