        return function () {
          removeTagState();
          document.body.removeAttribute(BODY_ATTR);
          for (var s2 = 0; s2 < SKIN_ATTRS.length; s2++) document.body.removeAttribute(SKIN_ATTRS[s2]);
          if (styleTag !== null) { styleTag.remove(); styleTag = null; }
          if (tokenDisposer !== null) { try { tokenDisposer(); } catch (e4) {} tokenDisposer = null; }
          if (themeRegistration !== null) { try { themeRegistration(); } catch (e11) {} themeRegistration = null; }
        };
